    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]; out=[row[:] for row in g]
    def bfs(r,c):
        x=g[r][c]; q=deque([(r,c)]);seen[r][c]=True;cells=[]
        while q:
            a,b=q.popleft();cells.append((a,b))
            for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                y,z=a+da,b+db
                if 0<=y<H and 0<=z<W and g[y][z]==x and not seen[y][z]:
                    seen[y][z]=True;q.append((y,z))
        return x,cells
    for r in range(H):
        for c in range(W):
            if g[r][c]!=3 and not seen[r][c]:
