                rs=[i for i,_ in cells]; cs=[j for _,j in cells]
                mn,mx=min(rs),max(rs); mn2,mx2=min(cs),max(cs)
                bbox=[(i,j) for i in range(mn,mx+1) for j in range(mn2,mx2+1)]
                onedge={(mn,i) for i in range(mn2,mx2+1)}|{(mx,i) for i in range(mn2,mx2+1)}|(set() or set())
